{
  "name": "USB通信端点",
  "name_en": "USB Endpoint",
  "manufacturer": "",
  "description": "用于与各类通过 USB 连接的实验仪器进行底层数据交换的通用通信端点。它通常存在于 USB 设备内部，用于主机与仪器之间传输命令、测量数据或状态信息，常见于数据采集设备、控制器和其他实验室电子仪器。",
  "description_en": "A generic low-level communication endpoint used to exchange data with laboratory instruments connected over USB. It typically exists within a USB device and is used to transfer commands, measurement data, or status information between the host and the instrument, commonly in data acquisition devices, controllers, and other electronic lab equipment.",
  "tag_hints": [
    "USB communication",
    "endpoint I/O",
    "instrument data transfer",
    "USB device control",
    "low-level hardware interface"
  ],
  "actions": [
    {
      "action_name": "auto-write",
      "description": "向 USB 端点写入数据",
      "description_en": "Write data to the USB endpoint"
    },
    {
      "action_name": "auto-read",
      "description": "从 USB 端点读取数据",
      "description_en": "Read data from the USB endpoint"
    },
    {
      "action_name": "auto-clear_halt",
      "description": "清除 USB 端点的暂停/错误状态",
      "description_en": "Clear the halt/error status of the USB endpoint"
    }
  ]
}

